import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "../styles/CreateArticlesAdmin.css";
import "../styles/components.css";

function CreateChannelPage() {
  const navigate = useNavigate();
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const token = localStorage.getItem("token");

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    setMessage("");

    if (!name.trim()) {
      setError("Назва каналу обов'язкова");
      return;
    }

    try {
      const res = await fetch("http://127.0.0.1:8000/api/channels/", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          name: name.trim(),
          description: description.trim() || "",
        }),
      });

      const data = await res.json();

      if (!res.ok) {
        setError(data.detail || data.name?.[0] || "Помилка створення каналу");
        return;
      }

      setMessage("Канал успішно створено!");
      setName("");
      setDescription("");
      
      // Redirect after 1 second
      setTimeout(() => {
        navigate("/subscriptions");
      }, 1000);
    } catch (err) {
      console.error("Помилка створення каналу:", err);
      setError("Помилка створення каналу, спробуйте ще раз");
    }
  };

  return (
    <div className="create-article-container">
      <h2 className="create-article-title">Створити канал</h2>
      {error && <div className="create-article-message error">{error}</div>}
      {message && <div className="create-article-message success">{message}</div>}
      
      <form onSubmit={handleSubmit} className="create-article-form">
        <label>
          Назва каналу:
          <input
            className="input"
            type="text"
            placeholder="Введіть назву каналу"
            value={name}
            onChange={(e) => setName(e.target.value)}
            required
          />
        </label>

        <label>
          Опис каналу (опціонально):
          <textarea
            className="input create-article-textarea"
            placeholder="Введіть опис каналу"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
          />
        </label>

        <button className="btn btn-primary" type="submit">
          Створити канал
        </button>
      </form>
    </div>
  );
}

export default CreateChannelPage;
